def test_moore_neighborhood_hypothesis():
    bg = 7

    def has_any_nobg(grid, r, c):
        """Check if any cell in Moore neighborhood is non-bg"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if grid[nr][nc] != bg:
                        return True
        return False

    def can_reach_nobg_along_line(grid, r, c):
        """Check if there's line-of-sight to non-bg in same row or col"""
        # Check row
        for kc in range(len(grid[0])):
            if kc != c and grid[r][kc] != bg:
                return True

        # Check col
        for kr in range(len(grid)):
            if kr != r and grid[kr][c] != bg:
                return True
        return False

    filled = set((r,c) for r in range(len(expected_d1)) for c in range(len(expected_d1[0])) 
                 if input_d1[r][c] == bg and expected_d1[r][c] == 1)

    # Test hypothesis: Filled = can_reach_nobg_along_line AND has_any_nobg
