                can_reach = can_reach_nobg_along_line(input_d1, r, c)
                has_neighbor = has_any_nobg(input_d1, r, c)
                pred = can_reach and has_neighbor
                actual = expected_d1[r][c] == 1

                if pred != actual:
                    mismatches.append(((r,c), pred, actual))

