def test_what_boundary_condition():
    """
    Looking at data, I notice:
    - Some cells within dist 2 of nobg are filled, others aren't
    - What distinguishes them?

    Hypothesis: Maybe we need bidirectionality in at least one dimension,
    OR we need to be able to go THROUGH another bg cell to reach nobg?
    """
    bg = 7

    def dist_to_nobg(grid, r, c, max_steps):
        """Distance to nearest non-bg using orthogonal movement"""
        visited = set()
        queue = [(r,c,0)]

        while queue:
            cur_r, cur_c, steps = queue.pop(0)

            if cur_r != r or cur_c != c:
                # Check if current cell is non-bg
                val = grid[cur_r][cur_c]
                if val != bg:
                    return steps

            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cur_r+dr, cur_c+dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if (nr,nc) not in visited and grid[nr][nc] == bg:
                        visited.add((nr,nc))
                        queue.append((nr, nc, steps+1))

        return float('inf')

    def requires_channel(grid, r, c):
        """Check if reaching non-bg requires passing through another bg cell first"""
        # Direct adjacency
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] != bg:
                    return False  # Direct neighbor

        # Two-step path (through one bg)
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == bg:
                    # Check if that neighbor can see non-bg directly
                    for ddr, ddc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nnr, nnc = nr+ddr, nc+ddc
                        if 0 <= nnr < len(grid) and 0 <= nnc < len(grid[0]):
